import numpy as np

class QPTestCase(unittest.TestCase):
    def setUp(self):
        self.test_states = {
            "zero": self._prepare_state(0),         # θ = 0 → |0⟩
            "plus": self._prepare_state(pi/4),       # θ = π/4
            "one": self._prepare_state(pi/2),        # θ = π/2 → |1⟩
        }
        self.generated_circuit = cir_generated

    def _prepare_state(self, theta):
        qc = QuantumCircuit(1)
        qc.ry(2 * theta, 0)  
        return qc

    def _estimate_overlap(self, result):
        p0 = result.get("0", 0) / sum(result.values())
        overlap_squared = 2 * p0 - 1
        return np.clip(overlap_squared, 0, 1)

    def test_angle_estimation(self):
        for label, state in self.test_states.items():
            qc = self.generated_circuit(state)
            result = run_circuit(qc)
            overlap_sq = self._estimate_overlap(result)
            est_theta = np.arccos(np.sqrt(overlap_sq))
            expected_theta = {
                "zero": 0,
                "plus": pi/4,
                "one": pi/2
            }[label]

            self.assertAlmostEqual(est_theta, expected_theta, delta=0.2)

