from qiskit import QuantumCircuit, QuantumRegister, ClassicalRegister
from typing import List, Tuple
from itertools import product
from collections import defaultdict

def qaoa_sat_ansatz() -> QuantumCircuit:
    """
    Construct a QAOA quantum circuit for solving a fixed SAT problem using QUBO encoding.
    The SAT instance: (x1 ∨ ¬x2 ∨ x3) ∧ (¬x1 ∨ x2 ∨ ¬x3)
    Fixed QAOA parameters: beta = [0.5], gamma = [0.8]
    Shots (for future simulation): 10000

    Returns:
        QuantumCircuit: The QAOA ansatz circuit that encodes the SAT problem.
    """

    clauses = [[1, -2, 3], [-1, 2, -3]]
    beta = [1.11915324]
    gamma = [2.69610991]
    shots = 10000

    def get_violating_assignments(clause: List[int], n_vars: int) -> List[Tuple[int]]:
        violating = []
        for bits in product([0, 1], repeat=n_vars):
            satisfied = False
            for lit in clause:
                idx = abs(lit) - 1
                val = bits[idx]
                if (lit > 0 and val == 1) or (lit < 0 and val == 0):
                    satisfied = True
            if not satisfied:
                violating.append(bits)
        return violating

    def sat_to_qubo_weights(clauses: List[List[int]], n_vars: int):
        linear = defaultdict(int)
        quadratic = defaultdict(int)
        for clause in clauses:
            violating_assignments = get_violating_assignments(clause, n_vars)
            for bits in violating_assignments:
                for i in range(n_vars):
                    if bits[i]:
                        linear[i] += 1
                for i in range(n_vars):
                    for j in range(i + 1, n_vars):
                        if bits[i] and bits[j]:
                            quadratic[(i, j)] += 2
        return dict(linear), dict(quadratic)

    n_vars = max(abs(lit) for clause in clauses for lit in clause)
    linear, quadratic = sat_to_qubo_weights(clauses, n_vars)
    p = len(beta)

    qr = QuantumRegister(n_vars, 'q')
    cr = ClassicalRegister(n_vars, 'c')
    qc = QuantumCircuit(qr, cr)

    qc.h(qr)

    for i in range(p):
        for var, coeff in linear.items():
            qc.rz(coeff * gamma[i], qr[var])
        for (u, v), coeff in quadratic.items():
            qc.cx(qr[u], qr[v])
            qc.rz(coeff * gamma[i], qr[v])
            qc.cx(qr[u], qr[v])
        for var in range(n_vars):
            qc.rx(2 * beta[i], qr[var])

    qc.measure(qr, cr)
    return qc

